export type OverlayStyle = "none" | "minimal" | "live"
export type PaginatedHistory = { entries: HistoryEntry[]; has_more: boolean }
export type PasteMethod = "ctrl_v" | "direct" | "none" | "shift_insert" | "ctrl_shift_v" | "external_script"
export type PermissionAccess = "allowed" | "denied" | "unknown"
/**
 * Screen edge the macOS side pill docks to (bottom = bottom centre).
 */
export type PillSide = "left" | "right" | "bottom"
/**
 * Request format a post-processing endpoint speaks. Built-in providers have a
 * fixed format; only the custom provider lets the user change it.
 */
export type PostProcessApiFormat = 
/**
 * OpenAI-compatible Chat Completions (`/chat/completions`)
 */
"openai" | 
/**
 * Anthropic Messages (`/messages`)
 */
"anthropic"
export type PostProcessProvider = { id: string; label: string; base_url: string; allow_base_url_edit?: boolean; models_endpoint?: string | null; supports_structured_output?: boolean; api_format?: PostProcessApiFormat }
export type ProcessingStage = 
/**
 * Telling the voices on the call apart (before transcribing).
 */
"speakers" | "transcribing" | "summarizing"
export type RecordingRetentionPeriod = "never" | 
/**
 * Keep every recording and transcript; same as `Never` (never delete).
 */
"forever" | "preserve_limit" | "days_3" | "weeks_2" | "months_3"
export type Replacement = { id: string; from: string; to: string; auto_learned?: boolean }
/**
 * A retired ONNX model found on disk.
 */
export type RetiredModel = { id: string; name: string; size_mb: number; replacement_repo: string }
export type SecretMap = Partial<{ [key in string]: string }>
export type SecureInputStatus = { 
/**
 * Secure input is currently enabled (live check)
 */
enabled: boolean; 
/**
 * Enabled continuously long enough to be considered stuck (not just a
 * password field gaining momentary focus)
 */
sustained: boolean; culprit_pid: number | null; culprit_name: string | null; 
/**
 * Carbon fallback registrations are currently active
 */
fallback_active: boolean; 
/**
 * Binding ids shadow-registered with identical semantics
 */
covered_bindings: string[]; 
/**
 * Side-specific binding ids widened to match either side while shadowed
 */
degraded_bindings: string[]; 
/**
 * Binding ids that cannot fire at all (e.g. fn+key, registration failure)
 */
uncovered_bindings: string[]; 
/**
 * The user tried to record a shortcut while secure input was active.
 * Treated as user impact even when every binding is covered, so the
 * warning banner appears and explains why recording refused.
 */
recorder_blocked: boolean }
export type Segment = { 
/**
 * "mic" or "system".
 */
source: string; 
/**
 * What to show: "Me", "Them" (call audio not split by voice),
 * "Speaker 1", "Speaker 2", … or a name.
 */
speaker: string; 
/**
 * Which voice this is, fixed while `speaker` may be renamed: "me" (mic),
 * "them" (call audio not split), or "s1", "s2", … in order of first
 * appearance. Every line of one key shares one label.
 */
speaker_key: string; 
/**
 * From the start of the meeting.
 */
start_ms: number; end_ms: number; text: string }
/**
 * How the transcribe shortcut's key events drive a recording.
 */
export type ShortcutActivation = 
/**
 * Press to start, press again to stop.
 */
"toggle" | 
/**
 * Hold to record, release to stop.
 */
"push_to_talk" | 
/**
 * Hold to record and release to stop, or tap to keep recording until the
 * next press. Which one it was is decided by how long the key was held
 * (`hold_threshold_ms`).
 */
"hold_or_toggle"
export type ShortcutBinding = { id: string; name: string; description: string; default_binding: string; current_binding: string }
export type Snippet = { id: string; trigger: string; expansion: string }
export type SoundTheme = "marimba" | "pop" | "custom"
/**
 * Phase of the streaming overlay card, emitted to drive its UI state.
 */
export type StreamPhase = 
/**
 * Receiving audio / live text (or waiting for the stream to begin). Rust
 * does not emit this today; the frontend starts in this phase and Rust only
 * emits transitions away from it.
 */
"listening" | 
/**
 * Finalizing or post-processing — show a spinner.
 */
"working"
/**
 * Emitted to switch the streaming overlay to a working spinner.
 */
export type StreamPhaseEvent = { phase: StreamPhase; 
/**
 * Present only when `phase` is `Working`.
 */
kind?: StreamWorkKind | null }
export type StreamState = "off" | "starting" | "capturing" | 
/**
 * Running but only digital silence so far: for system audio this usually
 * means the "System Audio Recording" permission was denied.
 */
"silent" | "unavailable"
export type StreamStatus = { state: StreamState; detail: string | null }
/**
 * Live transcription snapshot emitted to the overlay during a streaming run.
 * `committed` is the append-only, flicker-free prefix; `tentative` is the
 * volatile suffix the model may still rewrite.
 */
export type StreamTextEvent = { committed: string; tentative: string }
/**
 * Semantic kind of "working" phase, used to localize the spinner label.
 */
export type StreamWorkKind = "transcribing" | "polishing"
export type StyleCategory = "personal" | "work" | "email" | "other"
export type StyleKind = "formal" | "casual" | "very_casual"
export type StyleSettings = { personal: StyleKind; work: StyleKind; email: StyleKind; other: StyleKind; auto_cleanup: boolean }
export type SummaryStatus = "pending" | "ready" | "unavailable" | "failed"
/**
 * UI appearance mode. `System` follows the OS `prefers-color-scheme`; `Light`
 * and `Dark` force one of the two palettes Lipik already ships.
 */
export type Theme = "system" | "light" | "dark"
export type TranscribeAcceleratorSetting = "auto" | "cpu" | "gpu"
export type Transform = { id: string; name: string; description: string; prompt: string; 
/**
 * 1..=9 for ⌥1..⌥9, or none.
 */
shortcut_index: number | null }
export type TransformSettings = { opt_in: boolean; auto_apply: AutoApply; items: Transform[] }
export type TypingTool = "auto" | "wtype" | "kwtype" | "dotool" | "ydotool" | "xdotool"
export type VadBackend = "silero" | "earshot"
export type WindowsMicrophonePermissionStatus = { supported: boolean; overall_access: PermissionAccess; device_access: PermissionAccess; app_access: PermissionAccess; desktop_app_access: PermissionAccess }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
